# This workflow prunes old workflow runs for an entire repository.

name: "Chore - Prune old builds"

permissions:
  actions: write

on:
  schedule:
    - cron: '0 1 * * *'
  workflow_dispatch:
jobs:
  prune:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Prune cancelled/skipped runs
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const cancelled = await github.rest.actions.listWorkflowRunsForRepo({
              owner: context.repo.owner,
              per_page: 100,
              repo: context.repo.repo,
              status: 'cancelled',
            });

            const skipped = await github.rest.actions.listWorkflowRunsForRepo({
              owner: context.repo.owner,
              per_page: 100,
              repo: context.repo.repo,
              status: 'skipped',
            });

            for (const response of [cancelled, skipped]) {
              for (const run of response.data.workflow_runs) {
                console.log(`Run id ${run.id} of '${run.name}' is a cancelled/skipped run. Deleting...`);
                await github.rest.actions.deleteWorkflowRun({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  run_id: run.id
                });
              }
            }

      - name: Prune runs older than 3 days
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const days_to_expiration = 3;
            const ms_in_day = 86400000;
            const now = Date.now();
            const pages = 5;

            // we don't want to prune old runs from test.yml
            // because we track the duration of runs over time

            const workflows = [
              'cleanup.yml',
              'helm-docs.yml',
              'label.yml',
              'lint-and-release.yml',
              'transfer.yml'
            ]

            let runs_to_delete = [];

            for (const workflow of workflows) {
              for (let page = 0; page < pages; page += 1) {
                let response = await github.rest.actions.listWorkflowRuns({
                  owner: context.repo.owner,
                  page: page,
                  per_page: 100,
                  repo: context.repo.repo,
                  workflow_id: workflow
                });

                if (response.data.workflow_runs.length > 0) {
                  for (const run of response.data.workflow_runs) {
                    if (now - Date.parse(run.created_at) > ms_in_day * days_to_expiration) {
                      runs_to_delete.push([run.id, run.name]);
                    }
                  }
                }
              }
            }

            for (const run of runs_to_delete) {
              console.log(`Run id ${run[0]} of '${run[1]}' is older than ${days_to_expiration} days. Deleting...`);
              try {
                await github.rest.actions.deleteWorkflowRun({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  run_id: run[0]
                });
              } catch (error) {
                // ignore errors
              }
            }

{{- $deploymentStrategyType := default "RollingUpdate" .Values.deploymentStrategyType -}}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "firefly-iii.fullname" . }}
  labels:
    {{- include "firefly-iii.labels" . | nindent 4 }}
spec:
  {{- if not .Values.autoscaling.enabled }}
  replicas: {{ .Values.replicaCount }}
  {{- end }}
  strategy:
    type: {{ $deploymentStrategyType }}
    {{- if (eq $deploymentStrategyType "RollingUpdate") }}
    rollingUpdate: {{- toYaml .Values.rollingUpdate | nindent 6 }}
    {{- end }}
  selector:
    matchLabels:
      {{- include "firefly-iii.appSelectorLabels" . | nindent 6 }}
  template:
    metadata:
      annotations:
        checksum/config: {{ include (print $.Template.BasePath "/configmap.yaml") . | sha256sum }}
        checksum/secret: {{ include (print $.Template.BasePath "/secret.yaml") . | sha256sum }}
        {{- with .Values.podAnnotations }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      labels:
        {{- include "firefly-iii.appSelectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
      - name: {{ .Chart.Name }}
        {{- with .Values.securityContext }}
        securityContext:
          {{- toYaml . | nindent 12 }}
        {{- end }}
        {{- with .Values.image }}
        image: "{{ coalesce $.Values.global.image.registry .registry }}/{{ .repository }}:{{ .tag | default (printf "version-%s" $.Chart.AppVersion) }}"
        imagePullPolicy: {{ coalesce $.Values.global.image.pullPolicy .pullPolicy }}
        {{- end }}
        {{- if or .Values.config.envValueFrom }}
        env:
        {{- range $key, $value := .Values.config.envValueFrom }}
          - name: {{ $key }}
            valueFrom: {{- $value | toYaml | nindent 16 }}
        {{- end }}
        {{- end }}
        {{- if or (.Values.config.env) (.Values.config.existingSecret) }}
        envFrom:
          - secretRef:
              name: {{ template "firefly-iii.fullname" . }}-app-key
          {{- if .Values.config.env }}
          - configMapRef:
              name: {{ template "firefly-iii.fullname" . }}
          {{- end }}
          {{- if .Values.config.existingSecret }}
          - secretRef:
              name: {{ .Values.config.existingSecret }}
          {{- else if .Values.secrets.env }}
          - secretRef:
              name: {{ template  "firefly-iii.fullname" . }}
          {{- end }}
        {{- end }}
        {{- if or (.Values.persistence.enabled) (.Values.extraVolumeMounts) }}
        volumeMounts:
          {{- with .Values.extraVolumeMounts }}
            {{- toYaml . | nindent 10 }}
          {{- end }}
          {{- if .Values.persistence.enabled }}
          - name: upload
            mountPath: "/var/www/html/storage/upload"
          {{- end }}
        {{- end }}
        ports:
          - name: http
            containerPort: 8080
            protocol: TCP
        livenessProbe:
          {{- with .Values.livenessProbe }}
            {{- toYaml . | nindent 10 }}
          {{- end }}
        readinessProbe:
          {{- with .Values.readinessProbe }}
            {{- toYaml . | nindent 10 }}
          {{- end }}
        startupProbe:
          {{- with .Values.startupProbe }}
            {{- toYaml . | nindent 10 }}
          {{- end }}

        {{- with .Values.resources }}
        resources:
          {{- toYaml . | nindent 12 }}
        {{- end }}
      {{- if or (.Values.persistence.enabled) (.Values.extraVolumes) }}
      volumes:
        {{- with .Values.extraVolumes }}
          {{- toYaml . | nindent 8 }}
        {{- end }}
        {{- if (.Values.persistence.enabled) }}
        - name: upload
          persistentVolumeClaim:
            claimName: {{ default (include "firefly-iii.fullname" .)  .Values.persistence.existingClaim }}
        {{- end }}
      {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

{{- $defaultSecretName := include "importer.fullname" . -}}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "importer.fullname" . }}
  labels:
    {{- include "importer.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      {{- include "importer.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      {{- with .Values.podAnnotations }}
      annotations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      labels:
        {{- include "importer.selectorLabels" . | nindent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: {{ .Chart.Name }}
          {{- with .Values.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          env:
            - name: FIREFLY_III_ACCESS_TOKEN
              valueFrom:
                secretKeyRef:
                  name: {{ .Values.fireflyiii.auth.existingSecret | default $defaultSecretName }}
                  key: accessToken
            - name: FIREFLY_III_URL
              value: {{ .Values.fireflyiii.url }}
            {{- if .Values.fireflyiii.vanityUrl }}
            - name: VANITY_URL
              value: {{ .Values.fireflyiii.vanityUrl }}
            {{- end }}
            - name: TRUSTED_PROXIES
              value: {{ .Values.trustedProxies | quote }}
          {{- if or .Values.config.envValueFrom }}
          {{- range $key, $value := .Values.config.envValueFrom }}
            - name: {{ $key }}
              valueFrom: {{- $value | toYaml | nindent 16 }}
          {{- end }}
          {{- end }}
          {{- if or (.Values.config.env) (.Values.config.existingSecret) }}
          envFrom:
            {{- if .Values.config.env }}
            - configMapRef:
                name: {{ template "importer.fullname" . }}
            {{- end }}
            {{- if .Values.config.existingSecret }}
            - secretRef:
                name: {{ .Values.config.existingSecret }}
            {{- end }}
          {{- end }}
          {{- if or .Values.config.files .Values.additionalVolumes }}
          volumeMounts:
          {{- with .Values.additionalVolumeMounts }}
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- if .Values.config.files }}
            {{- range .Values.config.files }}
            - name: files
              mountPath: {{ .mountPath }}/{{ .name }}
              subPath: {{ .name }}
            {{- end }}
          {{- end }}
          {{- end }}
          ports:
            - name: http
              containerPort: 8080
              protocol: TCP
          {{- with .Values.livenessProbe }}
          livenessProbe:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.readinessProbe }}
          readinessProbe:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- with .Values.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- if or .Values.config.files .Values.additionalVolumes }}
      volumes:
        - name: files
          secret:
            secretName: {{ include "importer.fullname" . }}-files
        {{- with .Values.additionalVolumes }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      {{- end }}

