{{- if and .Values.configs.BACKUP_ENABLED (eq .Values.backup.destination "pvc") (eq .Values.backup.pvc.existingClaim "") }}
apiVersion: v1
kind: PersistentVolumeClaim
metadata:
  namespace: {{ .Release.Namespace }}
  name: {{ printf "%s-%s" (include "firefly-db.fullname" .) "backup-storage-claim" }}
  labels:
    app: {{ template "firefly-db.name" . }}
    chart: {{ template "firefly-db.chart" . }}
    release: {{ .Release.Name }}
    heritage: {{ .Release.Service }}
spec:
  {{- with .Values.backup.pvc.class }}
  storageClassName: {{ . }}
  {{- end }}
  accessModes:
    - {{ .Values.backup.pvc.accessModes }}
  resources:
    requests:
      storage: {{ .Values.backup.pvc.dataSize }}
{{- end }}

{{- if .Values.configs.BACKUP_ENABLED }}
{{- if and (eq .Values.backup.destination "http") (empty .Values.configs.BACKUP_URL) }}
{{- fail "BACKUP_URL must be set when backup.destination is 'http'" }}
{{- end }}

apiVersion: batch/v1
kind: Job
metadata:
  namespace: {{ .Release.Namespace }}
  name: {{ template "firefly-db.fullname" . }}-backup-job
  labels:
    app: {{ template "firefly-db.name" . }}
    chart: {{ template "firefly-db.chart" . }}
    release: {{ .Release.Name }}
    heritage: {{ .Release.Service }}
  annotations:
    "helm.sh/hook": pre-delete,pre-upgrade
    "helm.sh/hook-weight": "-5"
    "helm.sh/hook-delete-policy": hook-succeeded
spec:
  backoffLimit: 0
  ttlSecondsAfterFinished: 100
  parallelism: 1
  completions: 1
  template:
    {{- include "backupJobSpec" . | indent 4 }}
{{- end }}

{{ if .Values.backupSchedule }}
apiVersion: batch/v1
kind: CronJob
metadata:
  namespace: {{ .Release.Namespace }}
  name: {{ template "firefly-db.fullname" . }}-backup
  labels:
    app: {{ template "firefly-db.name" . }}
    chart: {{ template "firefly-db.chart" . }}
    release: {{ .Release.Name }}
    heritage: {{ .Release.Service }}
spec:
  schedule: "{{ .Values.backupSchedule }}"
  successfulJobsHistoryLimit: 1
  failedJobsHistoryLimit: 1
  jobTemplate:
    spec:
      backoffLimit: 0
      template:
        {{- include "backupJobSpec" . | indent 8 }}
{{ end }}
